// On success, `*out_handle` is set to a newly allocated [`HurrayDescriptor`]
// that MUST be released via [`hurray_descriptor_destroy`].
//
// # Arguments
//
// - `bytes` — Non-null pointer to the first byte of the encoded descriptor.
// - `len` — Number of bytes readable at `bytes`.
// - `out_handle` — Non-null pointer to a `*mut HurrayDescriptor`; set on
//   success.
//
// # Safety
//
// - `bytes` MUST be valid and readable for `len` bytes for the duration of
//   this call.
// - `out_handle` MUST be a valid, non-null, writable pointer.

HurrayStatus hurray_descriptor_decode(const uint8_t *bytes,
                                      uintptr_t len,
                                      struct HurrayDescriptor **out_handle)
;

// Destroys a [`HurrayDescriptor`] handle and frees its memory.
//
// After this call, `handle` is no longer valid and MUST NOT be dereferenced.
//
// # Safety
//
// - `handle` MUST have been created by [`hurray_descriptor_decode`].
// - `handle` MUST NOT have been previously destroyed.
 HurrayStatus hurray_descriptor_destroy(struct HurrayDescriptor *handle) ;

// Reads the element type tag byte of the tensor descriptor.
//
// # Safety
//
// `handle` and `out_tag` MUST be valid, non-null pointers.

HurrayStatus hurray_descriptor_element_type_tag(const struct HurrayDescriptor *handle,
                                                uint8_t *out_tag)
;

// Reads a signed array field of the descriptor's layout payload.
//
// Signed because strides may be negative (reversed) or zero (broadcast), which
// an unsigned accessor would misreport. The capacity/length protocol is the one
// [`hurray_descriptor_layout_field_u64_array`] documents.
//
// # Errors
//
// As [`hurray_descriptor_layout_field_u64_array`].
//
// # Safety
//
// - `handle` and `out_len` MUST be valid, non-null pointers.
// - If `out_values` is non-null it MUST be writable for `capacity` × 8 bytes,
//   where `capacity` is the value at `*out_len` on entry.

HurrayStatus hurray_descriptor_layout_field_i64_array(const struct HurrayDescriptor *handle,
                                                      HurrayLayoutField field,
                                                      uint32_t level,
                                                      int64_t *out_values,
                                                      uintptr_t *out_len)
;

// Reads a scalar field of the descriptor's layout payload.
//
// Every scalar payload field in the format is unsigned or boolean, so all of
// them widen losslessly into `uint64_t`: a boolean reads as `0` or `1`, and a
// wire tag byte reads as its documented value.
//
// # Arguments
//
// - `handle` — Descriptor created by
//   [`hurray_descriptor_decode`](crate::hurray_descriptor_decode).
// - `field` — One of the `HURRAY_LAYOUT_FIELD_*` scalar constants.
// - `level` — Tiled nesting level to read; MUST be `0` for every other layout.
// - `out_value` — Non-null pointer; written only on [`HURRAY_OK`].
//
// # Errors
//
// - [`HURRAY_ERR_FIELD_NOT_APPLICABLE`] — `field` does not belong to this
//   descriptor's layout, or is not a scalar field.
// - [`HURRAY_ERR_FIELD_NOT_PRESENT`] — the field is optional and this
//   descriptor does not carry it.
// - [`HURRAY_ERR_INDEX_OUT_OF_BOUNDS`] — `level` exceeds the nesting depth, or
//   is non-zero for a layout that does not nest.
//
// # Safety
//
// `handle` and `out_value` MUST be valid, non-null pointers, and `handle` MUST
// NOT have been destroyed.

HurrayStatus hurray_descriptor_layout_field_u64(const struct HurrayDescriptor *handle,
                                                HurrayLayoutField field,
                                                uint32_t level,
                                                uint64_t *out_value)
;

// Reads an unsigned array field of the descriptor's layout payload.
//
// Uses the capacity/length in-out pattern
// [`hurray_descriptor_shape`](crate::descriptor::hurray_descriptor_shape) uses:
//
// 1. Set `*out_len` to the capacity of `out_values` in elements, or `0` if
//    `out_values` is null.
// 2. On return `*out_len` always holds the field's true length.
// 3. A null `out_values` or an insufficient capacity returns
//    [`HURRAY_ERR_BUFFER_TOO_SMALL`], so the caller can allocate and retry.
//
// # Errors
//
// As [`hurray_descriptor_layout_field_u64`], plus
// [`HURRAY_ERR_BUFFER_TOO_SMALL`] per the protocol above.
//
// # Safety
//
// - `handle` and `out_len` MUST be valid, non-null pointers.
// - If `out_values` is non-null it MUST be writable for `capacity` × 8 bytes,
//   where `capacity` is the value at `*out_len` on entry.

HurrayStatus hurray_descriptor_layout_field_u64_array(const struct HurrayDescriptor *handle,
                                                      HurrayLayoutField field,
                                                      uint32_t level,
                                                      uint64_t *out_values,
                                                      uintptr_t *out_len)
;

// Reads the layout tag byte of the tensor descriptor.
//
// # Safety
//
// `handle` and `out_tag` MUST be valid, non-null pointers.

HurrayStatus hurray_descriptor_layout_tag(const struct HurrayDescriptor *handle,
                                          uint8_t *out_tag)
;

// Reads the rank (number of dimensions) of the tensor descriptor.
//
// # Safety
//
// `handle` and `out_rank` MUST be valid, non-null pointers.
 HurrayStatus hurray_descriptor_rank(const struct HurrayDescriptor *handle, uint32_t *out_rank) ;

// Reads the shape (dimension sizes) of a tensor descriptor.
//
// This function uses a **capacity/length in-out pattern**:
//
// 1. Set `*out_rank` to the capacity of the `out_dims` array (number of
//    `uint64_t` elements it can hold), or to `0` if `out_dims` is null.
// 2. On return, `*out_rank` always contains the true rank of the tensor.
// 3. If `out_dims` is null OR the capacity was less than the true rank,
//    the function returns [`HURRAY_ERR_BUFFER_TOO_SMALL`] and `*out_rank`
//    contains the true rank so the caller can allocate and retry.
// 4. Otherwise the function writes the dimension sizes into `out_dims[0..rank]`
//    and returns [`HURRAY_OK`].
//
// # Safety
//
// - `handle` and `out_rank` MUST be valid, non-null pointers.
// - If `out_dims` is non-null it MUST be writable for `capacity` × 8 bytes,
//   where `capacity` is the value at `*out_rank` on entry.

HurrayStatus hurray_descriptor_shape(const struct HurrayDescriptor *handle,
                                     uint64_t *out_dims,
                                     uintptr_t *out_rank)
;

// Reads the ABI version recorded by the producing build.
//
// **Call this first.** It is the one accessor guaranteed to work on a context
// produced by any version of this ABI; every other accessor assumes a caller
// that has already compared this value against its own
// [`HURRAY_C_ABI_VERSION`](crate::HURRAY_C_ABI_VERSION) and found it
// compatible (ADR-034 § 4). That ordering is what lets later versions add
// accessors without breaking older consumers.
//
// # Safety
//
// `ctx` MUST be a live handle from [`hurray_tensor_context_new`], and `out`
// MUST be a valid, writable pointer.
//
// # Examples
//
// ```
// use hurray_ffi::tensor_context::{
//     hurray_tensor_context_abi_version, hurray_tensor_context_destroy,
//     hurray_tensor_context_new,
// };
// use hurray_ffi::{HurrayTensorContext, HURRAY_C_ABI_VERSION, HURRAY_OK};
//
// let mut ctx: *mut HurrayTensorContext = std::ptr::null_mut();
// unsafe {
//     hurray_tensor_context_new(
//         HURRAY_C_ABI_VERSION, std::ptr::null(), 0, std::ptr::null_mut(), None, &mut ctx,
//     );
// }
//
// let mut version: u32 = 0;
// assert_eq!(
//     unsafe { hurray_tensor_context_abi_version(ctx, &mut version) },
//     HURRAY_OK,
// );
// assert_eq!(version, HURRAY_C_ABI_VERSION);
//
// unsafe { hurray_tensor_context_destroy(&mut ctx) };
// ```

HurrayStatus hurray_tensor_context_abi_version(const struct HurrayTensorContext *ctx,
                                               uint32_t *out)
;

// Borrows the encoded tensor descriptor.
//
// The returned pointer is owned by `ctx` and is valid until the context is
// destroyed; the caller MUST NOT free it. Decode it with
// [`hurray_descriptor_decode`](crate::descriptor::hurray_descriptor_decode) to
// read the element type, shape, layout, and optional sections.
//
// `out_len` is `0` — and `out_bytes` null — for a context created without a
// descriptor.
//
// # Safety
//
// `ctx` MUST be a live handle from [`hurray_tensor_context_new`], and both out
// pointers MUST be valid and writable.
//
// # Examples
//
// ```
// use hurray_ffi::tensor_context::{
//     hurray_tensor_context_descriptor, hurray_tensor_context_destroy,
//     hurray_tensor_context_new,
// };
// use hurray_ffi::{HurrayTensorContext, HURRAY_C_ABI_VERSION, HURRAY_OK};
//
// let descriptor = [0x48u8, 0x52, 0x52, 0x59];
// let mut ctx: *mut HurrayTensorContext = std::ptr::null_mut();
// unsafe {
//     hurray_tensor_context_new(
//         HURRAY_C_ABI_VERSION,
//         descriptor.as_ptr(),
//         descriptor.len() as u64,
//         std::ptr::null_mut(),
//         None,
//         &mut ctx,
//     );
// }
//
// let mut bytes: *const u8 = std::ptr::null();
// let mut len: u64 = 0;
// assert_eq!(
//     unsafe { hurray_tensor_context_descriptor(ctx, &mut bytes, &mut len) },
//     HURRAY_OK,
// );
// assert_eq!(len, 4);
// assert_eq!(unsafe { std::slice::from_raw_parts(bytes, len as usize) }, &descriptor);
//
// unsafe { hurray_tensor_context_destroy(&mut ctx) };
// ```

HurrayStatus hurray_tensor_context_descriptor(const struct HurrayTensorContext *ctx,
                                              const uint8_t **out_bytes,
                                              uint64_t *out_len)
;

// Destroys a [`HurrayTensorContext`], invoking its owner-release callback, and
// nulls the caller's pointer.
//
// Destroying a null handle is a no-op that returns [`HURRAY_OK`], so the call
// is safe to make unconditionally on a cleanup path.
//
// # Safety
//
// - `ctx` MUST be a valid, writable pointer to a handle slot.
// - The handle it points to MUST come from [`hurray_tensor_context_new`] and
//   MUST NOT have been destroyed already.
//
// # Examples
//
// ```
// use hurray_ffi::tensor_context::{hurray_tensor_context_destroy, hurray_tensor_context_new};
// use hurray_ffi::{HurrayTensorContext, HURRAY_C_ABI_VERSION, HURRAY_OK};
//
// let mut ctx: *mut HurrayTensorContext = std::ptr::null_mut();
// unsafe {
//     hurray_tensor_context_new(
//         HURRAY_C_ABI_VERSION, std::ptr::null(), 0, std::ptr::null_mut(), None, &mut ctx,
//     );
// }
//
// assert_eq!(unsafe { hurray_tensor_context_destroy(&mut ctx) }, HURRAY_OK);
// assert!(ctx.is_null());
// // Destroying again is a no-op, not a double free.
// assert_eq!(unsafe { hurray_tensor_context_destroy(&mut ctx) }, HURRAY_OK);
// ```
 HurrayStatus hurray_tensor_context_destroy(struct HurrayTensorContext **ctx) ;

// Creates a [`HurrayTensorContext`] owning a copy of `descriptor_bytes`.
//
// `abi_version` MUST be the producing build's `HURRAY_C_ABI_VERSION`; a consumer
// compares it against its own before trusting anything else about the capsule.
//
// `owner` and `owner_release` are optional and opaque. When `owner_release` is
// non-null it is invoked exactly once, with `owner`, during
// [`hurray_tensor_context_destroy`].
//
// The caller owns the returned handle and MUST destroy it exactly once.
//
// # Safety
//
// - `out_ctx` MUST be a valid, non-null, writable pointer.
// - `descriptor_bytes` MUST point to at least `descriptor_len` readable bytes,
//   unless `descriptor_len` is `0`, in which case it MAY be null.
// - `owner` MUST remain valid until `owner_release` is invoked.
//
// # Examples
//
// ```
// use hurray_ffi::tensor_context::{
//     hurray_tensor_context_destroy, hurray_tensor_context_new,
// };
// use hurray_ffi::{HurrayTensorContext, HURRAY_C_ABI_VERSION, HURRAY_OK};
//
// let descriptor = [0x48u8, 0x52, 0x52, 0x59]; // "HRRY"
// let mut ctx: *mut HurrayTensorContext = std::ptr::null_mut();
// assert_eq!(
//     unsafe {
//         hurray_tensor_context_new(
//             HURRAY_C_ABI_VERSION,
//             descriptor.as_ptr(),
//             descriptor.len() as u64,
//             std::ptr::null_mut(),
//             None,
//             &mut ctx,
//         )
//     },
//     HURRAY_OK,
// );
//
// assert_eq!(unsafe { hurray_tensor_context_destroy(&mut ctx) }, HURRAY_OK);
// assert!(ctx.is_null()); // destroy nulls the caller's pointer
// ```

HurrayStatus hurray_tensor_context_new(uint32_t abi_version,
                                       const uint8_t *descriptor_bytes,
                                       uint64_t descriptor_len,
                                       void *owner,
                                       HurrayOwnerReleaseFn owner_release,
                                       struct HurrayTensorContext **out_ctx)
;

#endif  /* HURRAY_H */
